    def test_low_stock_threshold_can_be_overridden_by_environment(self):
        with patch.dict(os.environ, {"LOW_STOCK_THRESHOLD": "31"}):
            self.assertEqual(low_stock(ITEMS), ["bolt", "nut"])


if __name__ == "__main__":
    unittest.main()

